<?php require_login();$data=cart_details();if(!$data['items']){flash('Your bag is empty.','warn');redirect('shop');}$user=auth();?><section class="page-heading compact"><div class="container"><span class="eyebrow">THE LAST LITTLE STEP</span><h1>Secure <em>checkout.</em></h1></div></section><section class="container section"><div class="cart-layout"><form class="checkout-form" method="post" action="<?=h(url('checkout'))?>"><?=csrf_input()?><input type="hidden" name="action" value="checkout"><h2>Delivery details</h2><div class="field"><label for="customer-name">Full name</label><input id="customer-name" name="name" value="<?=h($user['name'])?>" maxlength="100" minlength="2" required></div><div class="field"><label for="phone">Phone number</label><input id="phone" name="phone" type="tel" maxlength="30" placeholder="+962 7X XXX XXXX" required></div><div class="field"><label for="address">Delivery address</label><textarea id="address" name="address" maxlength="255" minlength="8" required placeholder="City, neighborhood, street and building"></textarea></div><div class="field"><label for="note">Order note (optional)</label><textarea id="note" name="note" maxlength="500" placeholder="Anything we should know?"></textarea></div><h2>How would you like it?</h2><label class="radio-option"><input type="radio" name="payment_method" value="cod" checked> Cash on delivery <span>Pay on arrival</span></label><label class="radio-option"><input type="radio" name="payment_method" value="pickup"> Pickup in store <span>No delivery fee</span></label><p class="micro">Academic demo: No online card payments are processed.</p><button class="btn btn-primary full" type="submit">Place your order ↗</button></form><aside class="summary-card"><h2>Your treats</h2><?php foreach($data['items'] as $item):?><div class="summary-line"><span><?=intval($item['qty'])?> × <?=h($item['name'])?></span><b><?=h(money($item['line_total']))?></b></div><?php endforeach;?><hr><div class="summary-line total"><span>Subtotal</span><strong><?=h(money($data['subtotal']))?></strong></div><p class="micro">Delivery: 2.00 JOD (free for 25+ JOD or pickup). Final total is confirmed on order placement.</p></aside></div></section>
